from pathlib import Path
import re,html,json
p=Path('sez-in-a-box.html');s=p.read_text();log=[]
def plain(x): return re.sub(r'\s+',' ',html.unescape(re.sub('<[^>]+>','',x))).strip()
def para(prefix,new,refs=()):
 global s
 found=[m for m in re.finditer(r'<p\b[^>]*>.*?</p>',s,re.S) if plain(m.group()).startswith(prefix)]
 assert len(found)==1,(prefix,len(found))
 m=found[0];old=m.group();body=html.escape(new,quote=False)
 for label,url in refs: body+=' <a href="'+html.escape(url,quote=True)+'">'+html.escape(label)+'</a>.'
 replacement='<p class="c0"><span class="c1">'+body+'</span></p>' if new else ''
 s=s[:m.start()]+replacement+s[m.end():];log.append({'prefix':prefix,'old_text':plain(old),'new_text':plain(replacement),'old_html':old,'new_html':replacement,'sources':refs})
# Narrow claims to what their stated evidence can establish.
para('The tax incentives, while important',"Shannon's early incentives included exemption from tax on qualifying trading profits. A later regime, effective from 1 January 1981, applied an effective corporation-tax rate of up to 10% to manufacturing profits across Ireland; the Finance Act 1981 extended it to qualifying non-manufacturing activities at Shannon. Companies protected by earlier relief could continue claiming it until 5 April 1990. Ireland's general 12.5% rate on trading income took effect in 2003.", [('Dáil Committee on Public Expenditure, 29 April 1986, §3.12','https://archive.oireachtas.ie/1986/REPORT_29041986_1.html'),('Revenue, Annual Report 1985, p. 179','https://www.revenue.ie/ga/rev-100/annual-report/1980/1985.pdf'),('Revenue, May 2015, p. 1','https://www.revenue.ie/en/tax-professionals/tdm/income-tax-capital-gains-tax-corporation-tax/part-02/02-02-02-20150529140745.pdf')])
para('Operational success within a zone',"Operational success within a zone did not make all of its institutional records usable elsewhere. A company expanding from Shannon to Singapore could bring its commercial history, but the receiving authorities still needed evidence that met their own registration, licensing, and compliance requirements. Recognition agreements could reduce some of that repeated work.")
para('Shannon also demonstrated the limitations',"Shannon also raises a question about the reach of a successful zone. Local services and institutional knowledge may benefit businesses nearby without becoming readily usable in another legal system. The network proposal addresses the work required to transfer that knowledge and recognize the records it produces.")
para("Shannon's record raises the next question", "Shannon's record raises the next question: how can other zones use innovations embedded in its local institutions? A network would need to document those practices, establish which records can be recognized elsewhere, and test their usefulness under the receiving jurisdiction's rules.")
para('Consider a company that spent five years',"Consider a company that has spent five years building a compliance record in Singapore. When it expands to Dubai or London, that history may help it demonstrate reliability, but it does not itself supply the permissions required there. Translation, certification, updated checks, and local approvals can still make expansion expensive.")
para('The EDB\'s operations in the 1960s',"The EDB actively recruited investors and coordinated the services needed to establish operations. Its ability to connect investment promotion with industrial planning gave companies an identifiable counterpart. For a new zone, the relevant lesson is that an investment offer needs an institution capable of arranging the land, infrastructure, skills, and approvals on which the offer depends.")
para('But the research side proved more challenging',"Research capacity and commercial innovation require separate measures. Laboratories, publications, patents, clinical results, and viable businesses represent different outcomes. In 2009, Singapore's Ministry of Health described the second phase of its biomedical initiative as building translational and clinical research alongside basic science. The question for zone policy is how research connects to practical uses, and over what period those uses should be assessed.",[('Singapore Ministry of Health, 2009 biomedical sciences announcement','https://www.moh.gov.sg/newsroom/singapore-ramps-up-biomedical-sciences-effort-with-injection-of-s36m-into-medical-technology-research/')])
para('The digital economy push from 2014',"The Smart Nation initiative, launched in 2014, linked technology adoption with opportunities for innovation. Its initial platform plan included sharing protected sensor data, improving public services, and enabling businesses to create new services. It treated the city as a place to test and apply technology, with public infrastructure supporting private development.",[('IDA, Smart Nation Platform factsheet, June 2014, p. 3','https://www.imda.gov.sg/-/media/Imda/Files/Inner/About-Us/Newsroom/Media-Releases/2014/0617_smartnation/AnnexA_sn.pdf')])
para('This strategy played to Singapore\'s strengths',"This approach gives a zone two related tasks: attract firms that develop technology and provide conditions in which useful technology can be adopted. The balance depends on local skills, customers, research institutions, and regulatory requirements. Adoption can create opportunities for local improvement without guaranteeing that a global technology company will emerge.")
para('The recovery strategy revealed Singapore\'s adaptability',"The pandemic made digital services, remote work, border controls, and public-health conditions part of business continuity planning. For a connected zone, these are operating dependencies to review as circumstances change. An arrangement that works during normal travel may need a different procedure when people cannot cross a border.")
para('The early days of the Shenzhen SEZ',"Shenzhen's early development required new administrative procedures as well as physical construction. Opening a market involved decisions about investment, employment, land use, and finance. The following examples show why a zone's rules and institutions must develop alongside its factories.")
para('The first land auction in 1987',"Shenzhen's 1987 land-use-rights auction illustrated the distinction between ownership of land and rights to use it. Land could remain publicly owned while a transferable, time-limited right supported development. The broader lesson is that a new market requires legally defined rights and a procedure for transferring them.")
para('The environmental catastrophe that accompanied China\'s rise',"The environmental damage associated with rapid industrialization is part of its development cost. Aggregate growth cannot show whether particular communities, workers, or ecosystems benefited. A modern zone needs to measure pollution, resource use, and health effects alongside production, and assign responsibility for prevention and remediation.")
para('Perhaps most importantly, China\'s experience',"China's experience also shows why context matters. Market size, state capacity, infrastructure, international demand, and the timing of reform shaped its opportunities. A country adopting parts of the model must assess which of those conditions it shares and which it would need to build.")
para('The decision to build Jebel Ali Port',"The decision to build Jebel Ali Port in the late 1970s extended Dubai's investment in maritime capacity. A Government of Dubai announcement in August 1976 estimated the 74-berth harbor's cost at AED3 billion. The investment posed the central question for infrastructure-led development: would the services attract enough new activity to justify capacity built ahead of demand?",[('Government of Dubai, 2 August 1976','https://humanities-collections.exeter.ac.uk/dame/files/original/a246be78fb9c6ac176a3365bf131422ea7e553ea.pdf')])
para('The Middle East in the 1980s',"JAFZA's offer addressed ownership, taxation, customs, and administrative costs that foreign businesses had to evaluate when entering the region. These requirements differed by country and activity. A zone could distinguish itself by making the applicable terms clear and providing the services needed to operate under them.")
para('Dubai Media City, launched simultaneously',"Dubai Media City brought broadcasters, news organizations, and related services into a specialized location. Its appeal depended on facilities, regional access, and the permissions available to media businesses. A specialized zone's operating terms need to be assessed under its actual law; the presence of international firms does not establish unrestricted freedom of activity.")
para('Consistent leadership and commitment were perhaps',"Continuity of development policy helped Dubai and Abu Dhabi sustain investments across generations of leadership. Concentrated authority can speed decisions, but speed alone does not establish their quality. A zone must also provide environmental review, community participation, and a way to challenge decisions that affect people's rights.")
para('Environmental sustainability challenges everything',"The UAE's development raises substantial questions about energy and water use. Desalination supplies much of its potable water, alongside groundwater and other sources used for different purposes. Cooling, transport, construction, and water production all need to be included in an assessment of a zone's resource demands. The design question is how to provide those services reliably while reducing emissions and environmental damage.",[('UAE Government, water resources overview','https://u.ae/en/information-and-services/environment-and-energy/water-and-energy/water-')])
para('Social cohesion challenges grow',"An economy that relies on expatriate labor must also address residence, family life, participation, and long-term security. UAE citizenship is available to specified categories under conditions, including reforms announced in January 2021 for investors, professionals, and people with particular talents. Those routes do not by themselves answer how a zone includes its wider workforce or how residents can challenge unfair treatment.",[('Dubai Media Office, 30 January 2021','https://mediaoffice.ae/en/news/2021/jan/30-01/mohammed-bin-rashid')])
para('Jurisdictional portability also solves Africa\'s credibility',"A company may have difficulty demonstrating its record abroad when receiving institutions cannot readily verify its domestic evidence. A recognition agreement could help a Nigerian business present specified records to an authorized counterparty elsewhere. The counterparty would still assess the evidence, the business, and the risks relevant to the proposed activity. Portability can reduce an information problem; it does not remove commercial or country risk.")
para('Mauritius stands alone',"Mauritius provides a widely studied African example of export-oriented industrial development. Its transition from dependence on sugar toward a more diversified economy raises questions about market access, investment, administrative capacity, and the way zone benefits can reach firms outside a physical enclave.")
para('The island had avoided', '') if False else None
para('Yet Mauritius had advantages',"Mauritius had institutions and infrastructure that could support a change in economic activity, including ports, trading relationships, banks, and a legal system. Those inherited resources did not remove the harms of colonialism or the inequality of the plantation economy. The development question was how to adapt them to a broader range of businesses and employment.")
para('Employment and exports grew with the number',"Employment and exports grew as the enterprise-based regime developed. The EPZ Development Authority's historical series records 89,906 workers at December 1990 and 90,861 at December 1991. These dated observations establish substantial employment; they do not by themselves measure the regime's net effect on wages, household income, or employment elsewhere. Appendix B gives the source and distinguishes year-end observations from within-year peaks.")
para("Nigeria's SEZ experience shows", "Nigeria's experience shows why zone performance must be assessed at the level of the actual project. Resources and a large domestic market can support an investment case, but the services, sector, and operating arrangements of a particular zone determine which businesses can use it.")
para('The Calabar Free Trade Zone, established',"A 2011 World Bank study contrasted Calabar's manufacturing ambition with a zone serving the oil and gas sector near Port Harcourt. It reported limited manufacturing activity at Calabar despite substantial investment, while the sector-focused initiative had attracted considerably more employment. The comparison concerns that study's period; it shows why a zone's fit with existing economic activity matters.",[('Farole, World Bank, 2011, box 3.2, p. 78','https://documents1.worldbank.org/curated/en/996871468008466349/pdf/600590PUB0ID181onomic09780821386385.pdf')])
para("Infrastructure repeatedly falls short", "For manufacturers, unreliable power, water, roads, or port access can erase the value of an incentive. The operator needs to specify the service promised, the party responsible, the standard measured, and the remedy when it fails. Marketing material alone cannot establish that a facility delivers those services.")
para('The infrastructure problems reflect deeper',"Administrative coordination matters for the same reason. A one-stop office can help an investor navigate requirements, but its usefulness depends on the powers and cooperation of the authorities behind it. Customs, immigration, environmental review, employment, and land rights need defined responsibilities and working procedures.")
para('The corruption tax makes formal taxes irrelevant',"Unofficial payments, where they occur, add cost and uncertainty beyond published fees. A credible zone should make its charges and decision procedures visible, record requests and outcomes, and provide a route for complaints. Evaluating those arrangements requires evidence from actual operations.")
para('Security adds another layer of cost',"Security and community relations also belong in the operating plan. Businesses need protection for people and assets, and communities need a voice in decisions about land, employment, and services. The responsible institutions and the cost of their work should be explicit before investment begins.")
para('The Dangote Refinery, located',"The refinery in Lekki's southeast quadrant also illustrates why the development cannot be judged as a single concession. A large industrial project has its own financing, infrastructure, approvals, and operating record. Its performance should be assessed separately from neighboring zones and from the wider masterplan.")
para('The Nigerian paradox deepens',"The contrast between digital businesses and infrastructure-intensive production poses a useful question: which constraints does a particular activity actually face? Software, professional services, manufacturing, and logistics need different combinations of skills, finance, utilities, and administration. Zone design should follow those needs rather than assume one national verdict covers them all.")
para("Ethiopia's aggressive SEZ development", "Ethiopia's industrial-park program sought to attract export manufacturing through dedicated facilities and coordinated public investment. Its experience raises separate questions about factory conditions, wages, productivity, infrastructure outside the parks, and political continuity. Those questions need separate evidence; the model cannot be assessed from construction speed alone.")
para('But the success was superficial',"A May 2019 NYU Stern study reported entry-level base pay of about US$26 per month at Hawassa. It described Ethiopia's garment-sector base wage as the lowest among garment-producing countries, with incentives sometimes supplementing base pay. The report connected low pay and difficult living conditions with high turnover. That finding makes worker retention and welfare part of the operating case, alongside factory occupancy and exports.",[('NYU Stern, May 2019, pp. 1, 4, 9 and 12','https://bhr.stern.nyu.edu/wp-content/uploads/2024/02/NYUEthiopia_ONLINEREVISEDJUNE61.pdf')])
para('The productivity consequences were devastating',"High turnover can impose repeated recruitment and training costs. Inadequate food, housing, transport, and training can also affect performance. Measuring those relationships requires evidence about the jobs and workers concerned. A turnover rate above 100% does not mean every worker left: repeated vacancies can contribute several departures within the same year.")
para('The political implosion from 2018',"Political conflict can disrupt the conditions on which a park depends: transport, power, staff movement, market access, and the willingness of customers to place orders. Ethiopia's conflict illustrates why an operating plan must address risks outside the park boundary. Records held elsewhere may help a company establish its standing after disruption, but cannot protect a factory or guarantee continued access to export markets.")
para('The Ethiopian experience demonstrates',"The Ethiopian case makes political continuity, worker welfare, and connections to the surrounding economy central to the design question. Dedicated facilities cannot supply all of those conditions. A zone needs both an operating institution and a plan for dependencies it does not control.")
para('Since 2006, China has established',"Chinese-backed economic cooperation zones in Africa involve different developers, sectors, financing arrangements, and relationships with host governments. Their outcomes should be compared at that level. Appendix B distinguishes the Eastern Industrial Park, the Zambia–China zone, and Lekki's separately managed concessions.")
para('The physical development proceeded smoothly',"UNIDO's 2018 case study reported, from developer interviews, approximately 10,000 jobs and US$200 million invested by 82 resident companies at the Eastern Industrial Park by the end of 2017. These figures concern resident-company activity and the report's observation period. They do not establish the developer's own expenditure or a current employment total.",[('UNIDO, 2018, pp. 23–24','https://ipp.unido.org/sites/default/files/knowledge/2020-11/Industrial%20park%20development%20in%20Ethiopia%20case%20study%20report.pdf')])
para('But deeper examination reveals problems',"Employment and investment totals leave further questions about local participation. Which skilled jobs do local workers hold? Which inputs come from domestic suppliers? What training occurs, and can workers use those skills elsewhere? These measures help distinguish an enclave from a development that strengthens the surrounding economy.")
para('The environmental and social impacts raise',"Environmental and social performance require their own evidence. A zone should publish applicable waste and safety requirements, assign inspection responsibility, and provide procedures for community consultation and complaints. Neither foreign sponsorship nor rapid construction establishes that these obligations have been met.")
para('The zone does process copper',"For a processing zone, the relevant tests include local employment, supplier participation, training, value added, and environmental cost. The location of a processing plant alone cannot answer how much benefit remains in the host economy. Investment, annual output, and employment should also be reported separately, as the Zambia–China example in Appendix B shows.")
# Exact low-level corrections that preserve surrounding text and citations.
exact=[
("The dirham was pegged to the dollar, eliminating currency risk.","The dollar peg stabilized the dirham–dollar rate, while businesses retained other currency exposures."),
("The regulatory sandbox approach, pioneered by the UK but perfected by the UAE, showed how regulation could enable rather than constrain innovation.","Regulatory sandboxes offered a way to test specified activities under defined permissions and supervision."),
("Traditional regulators faced an impossible choice with new technologies like cryptocurrency: ban them (stifling innovation) or ignore them (risking disaster). The UAE created a third option: controlled experimentation.","Controlled experimentation requires limits on activity, safeguards for participants, and a decision about what follows the test."),
("The UAE proved that in an uncertain world, clarity is more valuable than laxity.","These cases suggest that clear rules can be part of a jurisdiction's offer to investors."),
("Ethiopia: The Authoritarian Gambit That Failed","Ethiopia: Industrial Parks and Their Dependencies"),
("Mauritius: The Exception That Proves the Rule","Mauritius: Enterprise-Based Export Development"),
("These additional costs can add 30-40% to operating expenses, eliminating any advantage from tax incentives or cheap labor.","These additional costs can reduce the advantage offered by tax incentives or lower labor costs."),
("Networked zones make a company's verified standing portable", "The proposed network would make specified evidence of a company's standing portable"),
("Networked zones seek to make those benefits transferable and immediately replicable.","The proposed network seeks to make specified records reusable under recognition agreements."),
("At machine speed", "through shared records"),
("at machine speed", "through shared records"),
("145-159.1: The Irish Innovation - Birth of the Modern SEZ (1959-1990)","145-159.")
]
for old,new in exact:
 a,b=html.escape(old,quote=False),html.escape(new,quote=False);n=s.count(a)
 if not n: print('NOT PRESENT',old);continue
 s=s.replace(a,b);log.append({'old_text':old,'new_text':new,'occurrences':n})
# Remove manuscript-outline comments; preserve exact raw spans in the audit log.
notes=re.search(r'<h2 id="historical-notes">Historical Notes</h2>\s*(.*?)\n\s*</div>\s*\n\s*<footer class="article-footer">',s,re.S)
assert notes
old=notes.group(0);replacement='</div>\n\n            <footer class="article-footer">'
s=s[:notes.start()]+replacement+s[notes.end():];log.append({'disposition':'author-outline notes removed; raw preserved','old_html':old,'new_html':replacement})
s=re.sub(r'<sup><a href="#cmnt\d+" id="cmnt_ref\d+">\[[a-z]+\]</a></sup>','',s)
s=re.sub(r'<li><a href="#historical-notes">Historical Notes</a></li>\s*','',s)
# TOC note markers were plain strings.
s=re.sub(r'(?<=[)\]])\[[a-z]+\](?=</a>)','',s)
# Remove one empty legacy wrapper immediately preceding the removed notes.
s=s.replace('<div><p class="c11"><span class="c10 c26"></span></p>\n</div>','')
p.write_text(s);Path('scratch/final-source-boundary-repairs.json').write_text(json.dumps(log,ensure_ascii=False,indent=2)+'\n')
print('Applied',len(log),'final boundary repairs')
